import React, { forwardRef } from "react";
import { TouchableOpacity, Text, View } from "react-native";
import { cva, type VariantProps } from "class-variance-authority";

import { DynamicIcon } from "@/components/custom/dynamic-icon";
import { WaveDotsLoader } from "@/components/loaders/wave-dots-loader";
import { ShineGradientWrapper } from "@/components/layout/shine-gradient-wrapper";

import { cn, type IconName } from "@/lib/utils";

const buttonVariants = cva(
    "flex-row items-center justify-center gap-2 mb-3 w-full border min-h-[52px]",
    {
        variants: {
            variant: {
                primary: "bg-primary border-transparent shadow-primary",
                secondary:
                    "bg-secondary border-secondary-foreground shadow-none",
            },
            disabled: {
                true: "bg-surface-muted shadow-none border-transparent",
            },
            roundness: {
                default: "rounded-2xl",
                full: "rounded-full",
                sm: "rounded-lg",
                none: "rounded-none",
            },
        },
        defaultVariants: {
            variant: "primary",
            disabled: false,
            roundness: "default",
        },
    },
);

const textVariants = cva("text-lg font-bold", {
    variants: {
        variant: {
            primary: "text-primary-foreground",
            secondary: "text-secondary-foreground",
        },
        disabled: { true: "text-foreground-disabled" },
    },
    defaultVariants: { variant: "primary", disabled: false },
});

export interface ActionButtonProps extends VariantProps<typeof buttonVariants> {
    title: string;
    icon?: IconName | string;
    iconPosition?: "pre" | "post";
    isLoading?: boolean;
    disabled?: boolean;
    onPress?: () => void;
    className?: string;
    textClassName?: string;
    hasGradient?: boolean;
    GradientColors?: [string, string, ...string[]];
}

export const ActionButton = React.forwardRef<
    React.ElementRef<typeof TouchableOpacity>,
    ActionButtonProps
>(
    (
        {
            title,
            icon,
            variant = "primary",
            iconPosition = "post",
            isLoading = false,
            disabled = false,
            onPress,
            className,
            textClassName,
            withShine = false,
            hasGradient = false,
            GradientColors = ["#8870e6", "#5f84e0", "#5f84e0"],
            roundness = "default",
            ...props
        },
        ref,
    ) => {
        const isDisabled = disabled || isLoading;
        const isWrapped = (withShine || hasGradient) && !isDisabled;

        const buttonContent = (
            <TouchableOpacity
                ref={ref}
                activeOpacity={0.9}
                disabled={isDisabled}
                onPress={onPress}
                className={cn(
                    buttonVariants({ variant, disabled: isDisabled }),
                    className,
                    isLoading ? "opacity-80" : "",
                    isWrapped ? "mb-0" : "",
                    hasGradient && !isDisabled
                        ? "bg-transparent shadow-none border-transparent"
                        : "",
                )}
                {...props}
            >
                {isLoading ? (
                    <WaveDotsLoader />
                ) : (
                    <>
                        {icon && iconPosition === "pre" && (
                            <DynamicIcon
                                name={icon as string}
                                size={20}
                                className={cn(
                                    textVariants({
                                        variant,
                                        disabled: isDisabled,
                                    }),
                                    textClassName,
                                )}
                            />
                        )}
                        <Text
                            className={cn(
                                textVariants({ variant, disabled: isDisabled }),
                                textClassName,
                            )}
                        >
                            {title}
                        </Text>
                        {icon && iconPosition === "post" && (
                            <DynamicIcon
                                name={icon as string}
                                size={20}
                                className={cn(
                                    textVariants({
                                        variant,
                                        disabled: isDisabled,
                                    }),
                                    textClassName,
                                )}
                            />
                        )}
                    </>
                )}
            </TouchableOpacity>
        );

        if (isWrapped) {
            return (
                <ShineGradientWrapper
                    colors={GradientColors}
                    className={cn(
                        "w-full rounded-full mb-3",
                        roundness === "full"
                            ? "rounded-full"
                            : roundness === "sm"
                              ? "rounded-lg"
                              : roundness === "none"
                                ? "rounded-none"
                                : "rounded-2xl",
                        className,
                    )}
                    isShining={withShine}
                    hasGradient={hasGradient}
                >
                    {buttonContent}
                </ShineGradientWrapper>
            );
        }

        return buttonContent;
    },
);
ActionButton.displayName = "ActionButton";

import React, { useState, useEffect, forwardRef } from "react";
import { View, Text, TouchableOpacity, ViewProps } from "react-native";

import { cn } from "@/lib/utils";

export interface CountdownTimerProps extends ViewProps {
    initialMinutes?: number;
    initialSeconds?: number;
    timerText?: string;
    onResend: () => void;
}

export const CountdownTimer = forwardRef<
    React.ElementRef<typeof View>,
    CountdownTimerProps
>(
    (
        {
            initialMinutes = 0,
            initialSeconds = 60,
            timerText = "Resend code in",
            onResend,
            className,
            ...props
        },
        ref,
    ) => {
        const totalStartingSeconds = initialMinutes * 60 + initialSeconds;
        const [timeLeft, setTimeLeft] = useState(totalStartingSeconds);

        useEffect(() => {
            if (timeLeft <= 0) return;

            const interval = setInterval(() => {
                setTimeLeft((prev) => prev - 1);
            }, 1000);

            return () => clearInterval(interval);
        }, [timeLeft]);

        const handleResendPress = () => {
            setTimeLeft(totalStartingSeconds);
            onResend();
        };

        const formatTime = () => {
            const mins = Math.floor(timeLeft / 60);
            const secs = timeLeft % 60;
            return `${mins.toString().padStart(2, "0")}:${secs.toString().padStart(2, "0")}`;
        };

        return (
            <View
                ref={ref}
                className={cn(
                    "flex-row items-center justify-center",
                    className,
                )}
                {...props}
            >
                <Text className="text-sm text-foreground-muted">
                    {timerText}{" "}
                </Text>
                <TouchableOpacity
                    onPress={handleResendPress}
                    disabled={timeLeft > 0}
                >
                    <Text
                        className={cn(
                            "font-bold text-primary",
                            timeLeft > 0 ? "text-base" : "text-sm",
                        )}
                    >
                        {timeLeft > 0 ? formatTime() : "Resend Now"}
                    </Text>
                </TouchableOpacity>
            </View>
        );
    },
);
CountdownTimer.displayName = "CountdownTimer";

import React from "react";
import { View } from "react-native";
import Animated, {
    useAnimatedStyle,
    withTiming,
} from "react-native-reanimated";

import { cn } from "@/lib/utils";

export interface DotSlashPaginationProps {
    data: any[];
    activeIndex: number;
    className?: string;
}

export function DotSlashPagination({
    data,
    activeIndex,
    className,
}: DotSlashPaginationProps) {
    return (
        <View className={cn("flex-row items-center gap-1.5", className)}>
            {data?.map((_, index) => {
                const isActive = activeIndex === index;

                // Smoothly animate the width transition
                const animatedStyle = useAnimatedStyle(() => ({
                    width: withTiming(isActive ? 24 : 8, { duration: 300 }),
                }));

                return (
                    <Animated.View
                        key={index}
                        style={animatedStyle}
                        className={cn(
                            "h-2 rounded-full",
                            isActive ? "bg-primary" : "bg-slate-200", // Tailwind equivalent of #E2E8F0
                        )}
                    />
                );
            })}
        </View>
    );
}

import React from "react";
import * as LucideIcons from "lucide-react-native";
import { cssInterop } from "nativewind";

// Embedded types for 100% portability
export interface DynamicIconProps {
    name: string;
    size?: number;
    className?: string;
    color?: string;
}

const interopedIcons = new Set<string>();

export function DynamicIcon({
    name,
    className,
    color,
    size = 20,
}: DynamicIconProps) {
    // Grab the specific icon from the Lucide object using bracket notation
    const IconComponent = LucideIcons[name as keyof typeof LucideIcons] as any;

    // Fallback just in case a typo is passed
    if (!IconComponent) {
        console.warn(`Icon "${name}" does not exist in lucide-react-native.`);
        return null;
    }

    if (!interopedIcons.has(name)) {
        cssInterop(IconComponent, {
            className: {
                target: "style",
                nativeStyleToProp: {
                    color: true,
                    opacity: true,
                },
            },
        });
        // Add to cache so this block never runs for this icon again
        interopedIcons.add(name);
    }

    // Note: We pass color here as a fallback in case className doesn't dictate it
    return <IconComponent className={className} size={size} color={color} />;
}

import React from "react";
import { Text, TouchableOpacity } from "react-native";

import { HorizontalScroll } from "@/components/layout/horizontal-scroll";

import { cn } from "@/lib/utils";

export interface FilterChipsProps {
    filters: { label: string; value: string }[];
    activeFilter: string;
    onFilterChange: (filter: string) => void;
    className?: string;
}

export function FilterChips({
    filters,
    activeFilter,
    onFilterChange,
    className,
}: FilterChipsProps) {
    return (
        <HorizontalScroll className={className}>
            {filters?.map((filter) => {
                const isActive = activeFilter === filter?.value;
                return (
                    <TouchableOpacity
                        key={filter?.value}
                        onPress={() => onFilterChange(filter?.value)}
                        activeOpacity={0.7}
                        className={cn(
                            "px-4 py-3 rounded-2xl border-[1.3px]",
                            isActive
                                ? "border-primary bg-primary"
                                : "bg-transparent border-primary",
                        )}
                    >
                        <Text
                            className={cn(
                                "text-xs font-black",
                                isActive
                                    ? "text-primary-foreground"
                                    : "text-foreground",
                            )}
                        >
                            {filter?.label}
                        </Text>
                    </TouchableOpacity>
                );
            })}
        </HorizontalScroll>
    );
}

import React from "react";
import { View, Text, ViewProps } from "react-native";

import { DynamicIcon } from "@/components/custom/dynamic-icon";

import { cn, type IconName } from "@/lib/utils";

export interface FloatingChipInterface {
    label: string;
    value: string;
    icon: IconName | string;
    colorClass?: string; // e.g., "text-primary"
    bgClass?: string; // e.g., "bg-primary-lighter"
}

export interface FloatingChipProps extends ViewProps {
    leftItem: FloatingChipInterface;
    rightItem: FloatingChipInterface;
}

export function FloatingChip({
    leftItem,
    rightItem,
    className,
    ...props
}: FloatingChipProps) {
    // A helper to render each side identically
    const renderItem = (item: FloatingChipInterface) => (
        <View className="flex-1 flex-row items-center gap-3">
            <View
                className={cn(
                    "w-11 h-11 rounded-xl items-center justify-center",
                    item.bgClass || "bg-primary-lighter",
                )}
            >
                <DynamicIcon
                    name={item.icon as string}
                    size={20}
                    className={cn(item.colorClass || "text-primary")}
                />
            </View>

            {/* The Text Stack */}
            <View className="flex-1 justify-center">
                <Text className="text-xs font-medium text-foreground-muted mb-0.5">
                    {item.label}
                </Text>
                <Text
                    className="text-base font-bold text-foreground tracking-tight"
                    numberOfLines={1}
                    adjustsFontSizeToFit
                >
                    {item.value}
                </Text>
            </View>
        </View>
    );

    return (
        <View
            className={cn(
                "flex-row items-center justify-between p-3 bg-surface rounded-[24px] border-[0.5px] border-border shadow-sm",
                className,
            )}
            {...props}
        >
            {renderItem(leftItem)}
            <View className="w-[1px] h-10 bg-border mx-3" />
            {renderItem(rightItem)}
        </View>
    );
}

FloatingChip.displayName = "FloatingChip";

