import React, { forwardRef } from "react";
import { Pressable, Text, PressableProps, View } from "react-native";
import { cva, type VariantProps } from "class-variance-authority";

import { DynamicIcon } from "@/components/custom/dynamic-icon";

import { cn, type IconName } from "@/lib/utils";

const chipVariants = cva(
    "items-center justify-center gap-1.5 px-3 py-1.5 rounded-full border",
    {
        variants: {
            variant: {
                primary: "border-primary bg-primary-lighter",
                success: "border-success bg-success-bg",
                warning: "bg-orange-500/10 border-warning",
                destructive: "bg-destructive-bg border-destructive",
                muted: "border-border bg-surface",
            },
            iconPosition: {
                pre: "flex-row",
                post: "flex-row-reverse",
            },
        },
        defaultVariants: {
            variant: "primary",
            iconPosition: "pre",
        },
    },
);

const chipTextVariants = cva("text-xs font-extrabold", {
    variants: {
        variant: {
            primary: "text-primary",
            success: "text-success",
            warning: "text-warning",
            destructive: "text-destructive",
            muted: "text-foreground-muted",
        },
    },
    defaultVariants: {
        variant: "primary",
    },
});

export interface IconChipProps extends Omit<PressableProps, "className"> {
    label: string;
    icon?: IconName;
    iconPosition?: "pre" | "post";
    variant?: "primary" | "success" | "destructive" | "warning" | "muted";
    className?: string;
    copyable?: boolean;
}

export const IconChip = forwardRef<
    React.ElementRef<typeof View>,
    IconChipProps
>(
    (
        {
            label,
            variant = "primary",
            icon,
            iconPosition = "pre",
            className,
            copyable = false,
            onPress,
            ...props
        },
        ref,
    ) => {
        const handlePress = (e: any) => {
            if (copyable) {
                // TODO: Implement your clipboard/haptics logic here
                console.log(`Copied: ${label}`);
            }
            if (onPress) onPress(e);
        };

        return (
            <Pressable
                ref={ref}
                onPress={handlePress}
                disabled={!copyable && !onPress}
                className={cn(
                    chipVariants({ variant, iconPosition }),
                    className,
                )}
                {...props}
            >
                <DynamicIcon
                    name={icon}
                    size={14}
                    className={chipTextVariants({ variant })}
                />
                <Text className={chipTextVariants({ variant })}>{label}</Text>
            </Pressable>
        );
    },
);
IconChip.displayName = "IconChip";

import React, { forwardRef } from "react";
import { TouchableOpacity, TouchableOpacityProps } from "react-native";
import { cva, type VariantProps } from "class-variance-authority";

import { DynamicIcon } from "@/components/custom/dynamic-icon";

import { cn, type IconName } from "@/lib/utils";

const iconButtonVariants = cva(
    "items-center justify-center rounded-2xl border",
    {
        variants: {
            variant: {
                default:
                    "bg-surface border-border shadow-sm active:bg-surface-button",
                ghost: "bg-transparent border-transparent active:bg-slate-800/50",
            },
            size: {
                default: "w-16 h-16",
                sm: "w-12 h-12 rounded-xl",
                lg: "w-20 h-20 rounded-3xl",
            },
        },
        defaultVariants: {
            variant: "default",
            size: "default",
        },
    },
);

export interface IconOnlyButtonProps
    extends
        Omit<TouchableOpacityProps, "onPress" | "className">,
        VariantProps<typeof iconButtonVariants> {
    icon: IconName | string;
    onPress: () => void;
    iconColor?: string;
    className?: string;
    iconClassName?: string;
}

export const IconOnlyButton = forwardRef<
    React.ElementRef<typeof TouchableOpacity>,
    IconOnlyButtonProps
>(
    (
        {
            icon,
            variant,
            size,
            iconColor,
            className,
            iconClassName,
            onPress,
            ...props
        },
        ref,
    ) => {
        return (
            <TouchableOpacity
                ref={ref}
                activeOpacity={0.7}
                className={cn(iconButtonVariants({ variant, size }), className)}
                onPress={onPress}
                {...props}
            >
                <DynamicIcon
                    name={icon as string}
                    size={size === "sm" ? 20 : size === "lg" ? 32 : 24}
                    color={iconColor} // or "#94a3b8"
                    className={`text-foreground-muted ${iconClassName}`}
                />
            </TouchableOpacity>
        );
    },
);
IconOnlyButton.displayName = "IconOnlyButton";

import { useState, forwardRef } from "react";
import { Text, TextInput, View, TextInputProps } from "react-native";
import { Controller, FieldValues, Control, Path } from "react-hook-form";
import { cva, type VariantProps } from "class-variance-authority";

import { DynamicIcon } from "@/components/custom/dynamic-icon";

import { cn } from "@/lib/utils";

const inputWrapperVariants = cva(
    "flex-row items-center rounded-xl border bg-slate-900 overflow-hidden",
    {
        variants: {
            variant: {
                default: "border-slate-800",
                error: "border-destructive",
            },
            disabled: {
                true: "opacity-50 bg-slate-800/50",
            },
        },
        defaultVariants: {
            variant: "default",
            disabled: false,
        },
    },
);

export interface InputProps
    extends
        Omit<TextInputProps, "onChangeText">,
        VariantProps<typeof inputWrapperVariants> {
    label: string;
    value: string;
    onChangeText: (text: string) => void;
    error?: string;
    type?: "mobile" | "email" | "password" | "number" | "text";
    prefix?: string;
    className?: string; // Standardize user overrides
}

export interface ControlledInputProps<T extends FieldValues> extends Omit<
    InputProps,
    "value" | "onChangeText"
> {
    control: Control<T>;
    name: Path<T>;
}

export const Input = forwardRef<TextInput, InputProps>(
    (
        {
            label,
            value,
            type = "text",
            placeholder,
            maxLength,
            onChangeText,
            error,
            disabled,
            autoFocus = false,
            prefix = "+91",
            className,
            ...rest
        },
        ref,
    ) => {
        const [showSecureText, setShowSecureText] = useState(true);
        const hasError = !!error;

        return (
            <View className="mb-5">
                <Text className="text-xs font-medium text-slate-400 mb-2">
                    {label}
                </Text>

                <View
                    className={cn(
                        inputWrapperVariants({
                            variant: hasError ? "error" : "default",
                            disabled,
                        }),
                        className,
                    )}
                >
                    {type === "mobile" && (
                        <View className="justify-center px-4 border-r border-slate-800">
                            <Text className="text-base font-medium text-white">
                                {prefix}
                            </Text>
                        </View>
                    )}

                    <TextInput
                        ref={ref}
                        className="flex-1 px-4 py-4 text-base font-medium text-white"
                        placeholder={placeholder}
                        maxLength={maxLength}
                        placeholderTextColor="#64748b"
                        secureTextEntry={type === "password" && showSecureText}
                        keyboardType={
                            type === "mobile" || type === "number"
                                ? "number-pad"
                                : type === "email"
                                  ? "email-address"
                                  : "default"
                        }
                        autoCapitalize={
                            type === "email" || type === "password"
                                ? "none"
                                : "sentences"
                        }
                        value={value}
                        onChangeText={onChangeText}
                        autoFocus={autoFocus}
                        editable={!disabled}
                        {...rest}
                    />

                    {type === "password" && value?.length ? (
                        <DynamicIcon
