import React, { useEffect, forwardRef } from "react";
import { Pressable, View } from "react-native";
import Animated, {
    useSharedValue,
    useAnimatedStyle,
    withSpring,
    withTiming,
    interpolateColor,
} from "react-native-reanimated";
import * as Haptics from "expo-haptics";

import { DynamicIcon } from "@/components/custom/dynamic-icon";

import { cn, type IconName } from "@/lib/utils";

const SWITCH_SIZES = {
    sm: {
        trackW: 36,
        trackH: 20,
        thumb: 16,
        transOn: 18,
        transOff: 2,
        iconSize: 10,
    },
    default: {
        trackW: 44,
        trackH: 24,
        thumb: 20,
        transOn: 22,
        transOff: 2,
        iconSize: 12,
    },
    lg: {
        trackW: 52,
        trackH: 28,
        thumb: 24,
        transOn: 26,
        transOff: 2,
        iconSize: 16,
    },
};

export interface ToggleSwitchProps {
    value: boolean;
    onValueChange: (value: boolean) => void;
    size?: "sm" | "default" | "lg";
    customIcons?: {
        iconOn?: IconName;
        iconOff?: IconName;
    };
    disabled?: boolean;
    className?: string;
    activeColor?: string; // Exposed for Reanimated hex injection
    inactiveColor?: string;
}

export const ToggleSwitch = forwardRef<
    React.ElementRef<typeof View>,
    ToggleSwitchProps
>(
    (
        {
            value,
            onValueChange,
            size = "default",
            customIcons = { iconOn: "Check", iconOff: "X" },
            disabled = false,
            className,
            activeColor = "#5f84e0",
            inactiveColor = "#D1D5DB",
        },
        ref,
    ) => {
        const dimensions = SWITCH_SIZES[size];

        // Animation Values
        const translateX = useSharedValue(
            value ? dimensions.transOn : dimensions.transOff,
        );
        const progress = useSharedValue(value ? 1 : 0);

        useEffect(() => {
            translateX.value = withSpring(
                value ? dimensions.transOn : dimensions.transOff,
                {
                    damping: 20,
                    stiffness: 250,
                    mass: 0.5,
                },
            );
            progress.value = withTiming(value ? 1 : 0, { duration: 200 });
        }, [value, dimensions]);

        const handlePress = () => {
            if (disabled) return;
            Haptics.impactAsync(Haptics.ImpactFeedbackStyle.Light);
            onValueChange(!value);
        };

        // Reanimated requires raw hex strings, avoiding context hooks
        const trackAnimatedStyle = useAnimatedStyle(() => {
            const backgroundColor = interpolateColor(
                progress.value,
                [0, 1],
                [inactiveColor, activeColor],
            );
            return { backgroundColor };
        });

        const thumbAnimatedStyle = useAnimatedStyle(() => {
            return {
                transform: [{ translateX: translateX.value }],
            };
        });

        return (
            <Pressable
                ref={ref}
                onPress={handlePress}
                disabled={disabled}
                className={cn(
                    "rounded-full justify-center",
                    disabled ? "opacity-50" : "opacity-100",
                    className,
                )}
                style={{ width: dimensions.trackW, height: dimensions.trackH }}
            >
                <Animated.View
                    style={[trackAnimatedStyle]}
                    className="absolute w-full h-full rounded-full"
                />

                <Animated.View
                    style={[
                        thumbAnimatedStyle,
                        { width: dimensions.thumb, height: dimensions.thumb },
                    ]}
                    className="bg-white rounded-full items-center justify-center shadow-sm"
                >
                    {value ? (
                        <DynamicIcon
                            name={customIcons.iconOn as string}
                            size={dimensions.iconSize}
                            color={activeColor}
                        />
                    ) : (
                        <DynamicIcon
                            name={customIcons.iconOff as string}
                            size={dimensions.iconSize}
                            color={inactiveColor}
                        />
                    )}
                </Animated.View>
            </Pressable>
        );
    },
);
ToggleSwitch.displayName = "ToggleSwitch";

import { type ClassValue, clsx } from "clsx";
import { twMerge } from "tailwind-merge";
import * as LucideIcons from "lucide-react-native";

export function cn(...inputs: ClassValue[]) {
    return twMerge(clsx(inputs));
}

// Global Icon Type for the component registry
export type IconName = keyof typeof LucideIcons;

import React from "react";
import { View, Text, Pressable } from "react-native";
import Animated, {
    withSpring,
    useSharedValue,
    useAnimatedStyle,
} from "react-native-reanimated";

import { DynamicIcon } from "@/components/custom/dynamic-icon";

import { cn, type IconName } from "@/lib/utils";

export interface WatermarkGridCardProps {
    title: string;
    subtitle?: string;
    icon: IconName | string;
    onPress: () => void;
    iconClassName?: string; // Allows passing a specific Tailwind text color
    iconColor?: string; // Allows passing a raw hex color
    className?: string; // Controls the outer wrapper (default w-[48%])
}

export function WatermarkGridCard({
    title,
    subtitle,
    icon,
    onPress,
    iconClassName,
    iconColor,
    className,
}: WatermarkGridCardProps) {
    const scale = useSharedValue(1);

    const animatedStyle = useAnimatedStyle(() => ({
        transform: [{ scale: scale.value }],
    }));

    return (
        <Animated.View
            style={animatedStyle}
            className={cn("w-[48%] mb-4", className)}
        >
            <Pressable
                onPressIn={() => (scale.value = withSpring(0.94))}
                onPressOut={() => (scale.value = withSpring(1))}
                onPress={onPress}
                className="w-full h-40 bg-surface border border-border rounded-3xl p-4 overflow-hidden justify-between relative shadow-sm"
            >
                {/* THE ABSTRACT TILTED WATERMARK */}
                <View
                    className="absolute -right-2 -bottom-2 opacity-10"
                    style={{ transform: [{ rotate: "-15deg" }] }}
                >
                    <DynamicIcon
                        name={icon as string}
                        size={50}
                        className="text-primary"
                    />
                </View>

                {/* CARD CONTENT */}
                <View className="w-16 h-16 rounded-full items-center justify-center border-[0.5px] border-border bg-background">
                    <DynamicIcon
                        name={icon as string}
                        size={30}
                        className={iconClassName}
                        color={iconColor}
                    />
                </View>

                <View>
                    {subtitle && (
                        <Text className="text-[10px] font-medium text-foreground-muted uppercase">
                            {subtitle}
                        </Text>
                    )}
                    <Text className="text-base font-bold text-foreground">
                        {title}
                    </Text>
                </View>
            </Pressable>
        </Animated.View>
    );
}

import React, { useEffect } from "react";
import { View } from "react-native";
import Animated, {
    withDelay,
    withRepeat,
    withTiming,
    withSequence,
    useSharedValue,
    useAnimatedStyle,
} from "react-native-reanimated";

const Dot = ({ delay, color }: { delay: number; color: string }) => {
    const translateY = useSharedValue(0);
    const opacity = useSharedValue(0.4);

    useEffect(() => {
        translateY.value = withDelay(
            delay,
            withRepeat(
                withSequence(
                    withTiming(-6, { duration: 300 }),
                    withTiming(0, { duration: 300 }),
                ),
                -1,
                true,
            ),
        );
        opacity.value = withDelay(
            delay,
            withRepeat(
                withSequence(
                    withTiming(1, { duration: 300 }),
                    withTiming(0.4, { duration: 300 }),
                ),
                -1,
                true,
            ),
        );
    }, []);

    const style = useAnimatedStyle(() => ({
        transform: [{ translateY: translateY.value }],
        opacity: opacity.value,
    }));

    return (
        <Animated.View
            style={[
                style,
                {
                    width: 7,
                    height: 7,
                    borderRadius: 6,
                    backgroundColor: color,
                    marginHorizontal: 3,
                },
            ]}
        />
    );
};

export function WaveDotsLoader({ color = "#FFFFFF" }: { color?: string }) {
    return (
        <View className="flex-row items-center justify-center h-6">
            <Dot delay={0} color={color} />
            <Dot delay={150} color={color} />
            <Dot delay={300} color={color} />
        </View>
    );
}
